mapper.update:
UPDATE nginx_minute_stat
SET request_count = request_count + #{requestCount},
    sum_request_time_ms = sum_request_time_ms + #{sumRequestTimeMs},
    max_request_time_ms = CASE WHEN #{maxRequestTimeMs} > max_request_time_ms THEN #{maxRequestTimeMs} ELSE max_request_time_ms END,
    sum_upstream_time_ms = sum_upstream_time_ms + #{sumUpstreamTimeMs},
    status_2xx = status_2xx + #{status2xx},
    status_4xx = status_4xx + #{status4xx},
    status_5xx = status_5xx + #{status5xx},
    slow_count = slow_count + #{slowCount}
WHERE source_id = #{sourceId}
  AND bucket_time = #{bucketTime}
  AND client_ip = #{clientIp}
  AND uri = #{uri}
  AND method = #{method}

mapper.insert:
INSERT INTO nginx_minute_stat (
    source_id, bucket_time, client_ip, uri, method,
    request_count, sum_request_time_ms, max_request_time_ms, sum_upstream_time_ms,
    status_2xx, status_4xx, status_5xx, slow_count, create_time
) VALUES (
    #{sourceId}, #{bucketTime}, #{clientIp}, #{uri}, #{method},
    #{requestCount}, #{sumRequestTimeMs}, #{maxRequestTimeMs}, #{sumUpstreamTimeMs},
    #{status2xx}, #{status4xx}, #{status5xx}, #{slowCount}, #{createTime}
)

mapper.select:
SELECT client_ip AS "clientIp", SUM(request_count) AS "requestCount", SUM(status_4xx) AS "status4xx", SUM(status_5xx) AS "status5xx", SUM(slow_count) AS "slowCount" FROM nginx_minute_stat WHERE bucket_time >= #{startTime} AND bucket_time < #{endTime} AND source_id IN #{sid}
AND client_ip LIKE '%' || #{keyword} || '%'
GROUP BY client_ip ORDER BY SUM(request_count) DESC LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*) FROM (
    SELECT client_ip
    FROM nginx_minute_stat
    WHERE bucket_time >= #{startTime}
      AND bucket_time < #{endTime}
      AND source_id IN
      #{sid}

          AND client_ip LIKE '%' || #{keyword} || '%'

    GROUP BY client_ip
) t

SELECT uri AS "uri", SUM(request_count) AS "requestCount", SUM(status_4xx) AS "status4xx", SUM(status_5xx) AS "status5xx", SUM(slow_count) AS "slowCount", ROUND(SUM(sum_request_time_ms) * 1.0 / NULLIF(SUM(request_count), 0), 2) AS "avgRequestTimeMs" FROM nginx_minute_stat WHERE bucket_time >= #{startTime} AND bucket_time < #{endTime} AND source_id IN #{sid}
AND uri LIKE '%' || #{keyword} || '%'
GROUP BY uri ORDER BY SUM(request_count) DESC LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*) FROM (
    SELECT uri
    FROM nginx_minute_stat
    WHERE bucket_time >= #{startTime}
      AND bucket_time < #{endTime}
      AND source_id IN
      #{sid}

          AND uri LIKE '%' || #{keyword} || '%'

    GROUP BY uri
) t

SELECT client_ip AS "clientIp", uri AS "uri", method AS "method", SUM(request_count) AS "requestCount", SUM(slow_count) AS "slowCount", ROUND(SUM(sum_request_time_ms) * 1.0 / NULLIF(SUM(request_count), 0), 2) AS "avgRequestTimeMs" FROM nginx_minute_stat WHERE bucket_time >= #{startTime} AND bucket_time < #{endTime} AND source_id IN #{sid}
AND client_ip LIKE '%' || #{clientIp} || '%'
AND uri LIKE '%' || #{uri} || '%'
GROUP BY client_ip, uri, method ORDER BY SUM(request_count) DESC LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*) FROM (
    SELECT client_ip, uri, method
    FROM nginx_minute_stat
    WHERE bucket_time >= #{startTime}
      AND bucket_time < #{endTime}
      AND source_id IN
      #{sid}

          AND client_ip LIKE '%' || #{clientIp} || '%'


          AND uri LIKE '%' || #{uri} || '%'

    GROUP BY client_ip, uri, method
) t

SELECT COUNT(*) FROM (
    SELECT uri
    FROM nginx_minute_stat
    WHERE bucket_time >= #{startTime}
      AND bucket_time < #{endTime}
      AND source_id IN
      #{sid}
      AND slow_count > 0
    GROUP BY uri
) t

SELECT COALESCE(SUM(request_count), 0) AS "totalRequests",
       COALESCE(SUM(status_4xx), 0) AS "status4xx",
       COALESCE(SUM(status_5xx), 0) AS "status5xx",
       COALESCE(SUM(slow_count), 0) AS "slowCount"
FROM nginx_minute_stat
WHERE bucket_time >= #{startTime}
  AND bucket_time < #{endTime}
  AND source_id IN
  #{sid}

SELECT client_ip AS "clientIp", SUM(request_count) AS "requestCount"
FROM nginx_minute_stat
WHERE source_id = #{sourceId}
  AND bucket_time >= #{startTime}
  AND bucket_time < #{endTime}
GROUP BY client_ip
HAVING SUM(request_count) >= #{threshold}
ORDER BY SUM(request_count) DESC
LIMIT #{limit}

SELECT uri AS "uri", SUM(request_count) AS "requestCount"
FROM nginx_minute_stat
WHERE source_id = #{sourceId}
  AND bucket_time >= #{startTime}
  AND bucket_time < #{endTime}
GROUP BY uri
HAVING SUM(request_count) >= #{threshold}
ORDER BY SUM(request_count) DESC
LIMIT #{limit}

SELECT COALESCE(SUM(status_4xx), 0) AS "status4xx",
       COALESCE(SUM(status_5xx), 0) AS "status5xx",
       COALESCE(SUM(slow_count), 0) AS "slowCount",
       COALESCE(SUM(request_count), 0) AS "totalRequests"
FROM nginx_minute_stat
WHERE source_id = #{sourceId}
  AND bucket_time >= #{startTime}
  AND bucket_time < #{endTime}
